static int qm(const Model *m, QMat *dst, int *experts, const char *fmt, int layer, const char *part) {
    char name[320];
    snprintf(name, sizeof name, fmt, layer, part);
    return load_qmat(&m->st, name, m->cfg.group_size, dst, experts);
